import { createServerClient } from '@supabase/ssr';
import { cookies } from 'next/headers';

/**
 * Fungsi untuk mengambil profil user yang sedang login.
 * Menggunakan standar Next.js 15+ dengan asynchronous cookies.
 */
export async function getLoggedUserProfile() {
  // 1. Inisialisasi Cookie Store secara async (Wajib di Next.js 15)
  const cookieStore = await cookies();

  // 2. Buat Supabase Server Client
  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll();
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options)
            );
          } catch {
            // Error ini bisa diabaikan jika fungsi dipanggil dari Server Component
          }
        },
      },
    }
  );

  // 3. Ambil data sesi user dari Supabase Auth
  const { data: { user }, error: authError } = await supabase.auth.getUser();

  if (authError || !user) {
    return null;
  }

  // 4. Ambil data profil beserta relasi nama ruangan (master_ruangan)
  const { data: profile, error: profileError } = await supabase
    .from('profiles')
    .select(`
      id,
      full_name,
      role,
      ruangan_id,
      master_ruangan (
        nama_ruangan
      )
    `)
    .eq('id', user.id)
    .single();

  if (profileError || !profile) {
    console.error("Gagal mengambil profil:", profileError);
    return null;
  }

  return profile;
}