import { getLoggedUserProfile } from "@/services/auth";
import FormHarian from "@/components/forms/FormHarian";
import { redirect } from "next/navigation";

/**
 * Dashboard Perawat (Server Component)
 * Menggunakan standar Next.js 15+ asynchronous.
 */
export default async function PerawatDashboard() {
  // 1. Ambil profil user secara async. 
  // Pastikan di dalam getLoggedUserProfile sudah menggunakan await cookies().
  const profile = await getLoggedUserProfile();

  // 2. Proteksi Halaman: Jika tidak ada sesi atau bukan Perawat, arahkan ke login.
  if (!profile || profile.role !== 'Perawat') {
    redirect('/login');
  }

  // 3. Ambil nama ruangan dari relasi master_ruangan.
  const namaRuangan = profile.master_ruangan?.nama_ruangan || "Ruangan Tidak Terdaftar";

  return (
    <div className="min-h-screen bg-slate-50">
      <main className="max-w-4xl mx-auto p-6">
        {/* Header Dashboard */}
        <header className="mb-8 bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex flex-col gap-1">
            <h1 className="text-2xl font-bold text-slate-900">
              Selamat Datang, {profile.full_name || 'Petugas'}
            </h1>
            <div className="flex items-center gap-2 mt-2">
              <span className="flex h-3 w-3 rounded-full bg-green-500 animate-pulse"></span>
              <p className="text-slate-600 font-semibold uppercase text-sm tracking-wide">
                📍 Unit Kerja: <span className="text-blue-600">{namaRuangan}</span>
              </p>
            </div>
          </div>
        </header>

        {/* Form Surveilans Harian (Client Component) */}
        <section>
          <FormHarian />
        </section>
      </main>
    </div>
  );
}